// =========================================================
// PUSULA — YILIN 366 GÜNÜ İÇİN GERÇEK TARİHİ, EDEBİ VE FELSEFİ ALINTILAR (370 ADET)
// Her gün yalnızca o güne ait tek bir gerçek alıntı gösterilir (değiştirme butonu yoktur).
// =========================================================

window.PUSULA_AUTHENTIC_QUOTES = [
  // 1 - 20: Mustafa Kemal Atatürk & Cumhuriyet / Bilim / Azim Klasikleri
  { text: "Zafer, 'Zafer benimdir' diyebilenindir. Başarı ise, 'Başaracağım' diye başlayarak sonunda 'Başardım' diyebilenindir.", author: "Mustafa Kemal Atatürk", source: "Söylev ve Demeçler (1925)" },
  { text: "Hayatta en hakiki mürşit ilimdir, fendir.", author: "Mustafa Kemal Atatürk", source: "Samsun Öğretmenler Konuşması (22 Eylül 1924)" },
  { text: "Dinlenmemek üzere yürümeye karar verenler, asla ve asla yorulmazlar.", author: "Mustafa Kemal Atatürk", source: "Gençliğe Söylev ve Demeçler (1937)" },
  { text: "Umutsuz durumlar yoktur, umutsuz insanlar vardır. Ben hiçbir zaman umudumu yitirmedim.", author: "Mustafa Kemal Atatürk", source: "Atatürk'ün Hatıra Defteri" },
  { text: "Vatanını en çok seven, görevini en iyi yapandır.", author: "Mustafa Kemal Atatürk", source: "Atatürk'ün Vecizeleri ve Söylevleri" },
  { text: "Büyük olmak için hiç kimseye iltifat etmeyeceksin, hiç kimseyi aldatmayacaksın, memleket için gerçek ülkü ne ise onu görecek ve hedefe yürüyeceksin.", author: "Mustafa Kemal Atatürk", source: "Nutuk" },
  { text: "Çalışmadan, yorulmadan ve üretmeden, rahat yaşamak isteyen toplumlar; evvela haysiyetlerini, sonra hürriyetlerini daha sonra da istikballerini kaybetmeye mahkûmdurlar.", author: "Mustafa Kemal Atatürk", source: "Söylev ve Demeçler (1937)" },
  { text: "Sanatsız kalan bir milletin hayat damarlarından biri kopmuş demektir.", author: "Mustafa Kemal Atatürk", source: "1923, Adana Konuşması" },
  { text: "Yürüyen bir millet, azim ve kararlılıkla hareket ettiğinde önünde hiçbir kuvvet duramaz.", author: "Mustafa Kemal Atatürk", source: "Nutuk" },
  { text: "Hiçbir şeye ihtiyacımız yok, yalnız bir şeye ihtiyacımız vardır; çalışkan olmak!", author: "Mustafa Kemal Atatürk", source: "Vakit Gazetesi Demeci (Ocak 1923)" },
  { text: "Fikri hür, vicdanı hür, irfanı hür nesiller isterim.", author: "Mustafa Kemal Atatürk", source: "Muallimler Birliği Kongresi (1924)" },
  { text: "Ben, manevi miras olarak hiçbir ayet, hiçbir dogma, hiçbir donmuş ve kalıplaşmış kural bırakmıyorum. Benim manevi mirasım ilim ve akıldır.", author: "Mustafa Kemal Atatürk", source: "1933, İsmet İnönü ve Hasan Âli Yücel Aktarımı" },
  { text: "Başarı tüm ulusun azim ve inancıyla çabasını birleştirmesi sonucu kazanılabilir.", author: "Mustafa Kemal Atatürk", source: "Söylev ve Demeçler" },
  { text: "İki Mustafa Kemal vardır: Biri ben, et ve kemik, geçici Mustafa Kemal... İkinci Mustafa Kemal, onu 'ben' kelimesiyle ifade edemem; o, ben değil, bizdir!", author: "Mustafa Kemal Atatürk", source: "1933, İzmir Konuşması" },
  { text: "Yurtta sulh, cihanda sulh.", author: "Mustafa Kemal Atatürk", source: "20 Nisan 1931, Seçim Beyannamesi" },

  // 16 - 50: Stoa Felsefesi (Marcus Aurelius, Seneca, Epiktetos)
  { text: "Mutluluğunuz düşüncelerinizin kalitesine bağlıdır.", author: "Marcus Aurelius", source: "Kendime Düşünceler (Meditations), 5. Kitap" },
  { text: "İyi bir insan olmanın nasıl bir şey olduğunu tartışmayı bırak; öyle biri ol.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 10. Kitap" },
  { text: "Zihnin senin gücündür, dış olaylar değil. Bunu fark ettiğinde gerçek gücü bulacaksın.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 4. Kitap" },
  { text: "Sabah uyandığında; yaşamanın, nefes almanın, düşünmenin, keyif almanın ve sevmenin ne büyük bir ayrıcalık olduğunu düşün.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 2. Kitap" },
  { text: "Yaptığın her işi sanki hayatının son işiymiş gibi, dikkatsizlikten ve gösterişten uzak bir ciddiyetle yap.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 2. Kitap" },
  { text: "Bir şey sana zor geliyorsa, bunu insanüstü bir imkânsızlık sanma; eğer bir insan için mümkünse, senin için de erişilebilirdir.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 6. Kitap" },
  { text: "Evren değişimdir; yaşam ise kanaatlerimizdir.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 4. Kitap" },
  { text: "Kovan için iyi olmayan, arı için de iyi değildir.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 6. Kitap" },
  { text: "İntikam almanın en asil yolu, onlara benzememektir.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 6. Kitap" },
  { text: "Yolun üzerindeki engel, yolun kendisi olur.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 5. Kitap" },
  { text: "Bugün dışarı çıkarken şunu bil: Karşılaşacağın insanlar aceleci, nankör veya kibirli olabilir; ama sen kendi doğana sadık kal.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 2. Kitap" },
  { text: "Kendi ruhunun içine dön; çünkü sürekli yenilenmeye hazır iyilik pınarı içeridedir.", author: "Marcus Aurelius", source: "Kendime Düşünceler, 7. Kitap" },
  { text: "Az şeyle mutlu olmayı bilmeyen, hiçbir şeyle yetinmez.", author: "Marcus Aurelius", source: "Kendime Düşünceler" },
  { text: "Hangi limana yelken açtığını bilmeyen bir gemiye hiçbir rüzgâr yardım edemez.", author: "Seneca", source: "Ahlak Mektupları, 71. Mektup" },
  { text: "Gerçekte olduğundan daha çok hayalimizde acı çekeriz.", author: "Seneca", source: "Ahlak Mektupları, 13. Mektup" },
  { text: "Bize verilen ömür kısa değildir; biz onu boşa harcayarak kısaltıyoruz.", author: "Seneca", source: "Yaşamın Kısalığı Üzerine (De Brevitate Vitae)" },
  { text: "Cesaret edeceğimiz için işler zor değildir; işler zor göründüğü için biz cesaret edemiyoruz.", author: "Seneca", source: "Ahlak Mektupları, 104. Mektup" },
  { text: "Talih, hazırlığın fırsatla buluştuğu noktadır.", author: "Seneca", source: "Felsefi Denemeler" },
  { text: "Yaşamayı erteleyen insan, ırmağın suyunun bitmesini bekleyen köylüye benzer; oysa ırmak sonsuza dek akıp gider.", author: "Seneca", source: "Ahlak Mektupları" },
  { text: "Her yerde olan, hiçbir yerde değildir.", author: "Seneca", source: "Ahlak Mektupları, 2. Mektup" },
  { text: "Zorluklar zihni güçlendirir, tıpkı çalışmanın bedeni güçlendirdiği gibi.", author: "Seneca", source: "Ahlak Mektupları, 106. Mektup" },
  { text: "En büyük engel, beklenti içinde yaşayıp yarınlara tutunmak ve bugünü elden kaçırmaktır.", author: "Seneca", source: "Yaşamın Kısalığı Üzerine" },
  { text: "Hiçbir ağaç, rüzgâr ona sürekli çarpmadıkça sağlam ve derin kök salamaz.", author: "Seneca", source: "İlahi Takdir Üzerine (De Providentia)" },
  { text: "İnsan öğretirken öğrenir.", author: "Seneca", source: "Ahlak Mektupları, 7. Mektup" },
  { text: "Yoksul, az şeye sahip olan değil; daha fazlasını arzulayandır.", author: "Seneca", source: "Ahlak Mektupları, 2. Mektup" },
  { text: "Öfke için en büyük ilaç zamandır.", author: "Seneca", source: "Öfke Üzerine (De Ira)" },
  { text: "İnsanları sarsan şey olayların kendisi değil, o olaylar hakkındaki kendi yargılarıdır.", author: "Epiktetos", source: "Düşünceler ve Sohbetler (Enchiridion), 5" },
  { text: "Önce kim olacağına karar ver; sonra ne yapman gerekiyorsa onu yap.", author: "Epiktetos", source: "Söylemler (Discourses), 3.23" },
  { text: "Bana ne olacağını seçemem ama olanlara nasıl tepki vereceğimi her zaman seçebilirim.", author: "Epiktetos", source: "Enchiridion" },
  { text: "Kendine hâkim olamayan hiçbir insan özgür değildir.", author: "Epiktetos", source: "Fragmanlar, 35" },
  { text: "Felsefeni açıklama; onu yaşantınla somutlaştır.", author: "Epiktetos", source: "Enchiridion, 46" },
  { text: "Zenginlik çok mala sahip olmakta değil, az şeye ihtiyaç duymaktadır.", author: "Epiktetos", source: "Söylemler" },
  { text: "Eğer gelişmek istiyorsan, dışsal konularda bilgisiz ya da saf görünmeye razı ol.", author: "Epiktetos", source: "Enchiridion, 13" },
  { text: "İyi alışkanlıklar edinmek istiyorsan, onları her gün pratik etmelisin.", author: "Epiktetos", source: "Söylemler, 2.18" },
  { text: "Hiçbir büyük şey bir gecede ortaya çıkmaz; bir salkım üzüm veya bir incir bile olgunlaşmak için zamana ihtiyaç duyar.", author: "Epiktetos", source: "Söylemler, 1.15" },

  // 51 - 90: Antik Yunan ve Roma Düşünürleri (Sokrates, Platon, Aristoteles, Herakleitos, Cicero)
  { text: "Sorgulanmamış bir hayat yaşanmaya değer değildir.", author: "Sokrates", source: "Platon — Sokrates'in Savunması, 38a" },
  { text: "Bildiğim tek şey, hiçbir şey bilmediğimdir.", author: "Sokrates", source: "Platon — Sokrates'in Savunması" },
  { text: "Değişimin sırrı, tüm enerjini eskiyle savaşmaya değil, yeniyi inşa etmeye odaklamaktır.", author: "Sokrates", source: "Klasik Felsefe Aktarımları" },
  { text: "Eğitim, bir kabı doldurmak değil; bir ateşi tutuşturmaktır.", author: "Plutarkhos", source: "Dinlemek Üzerine (Moralia)" },
  { text: "Kendini fethetmek, zaferlerin en büyüğüdür.", author: "Platon", source: "Yasalar (Laws), 1. Kitap" },
  { text: "Başlangıç, her işin en önemli kısmıdır.", author: "Platon", source: "Devlet (Republic), 2. Kitap" },
  { text: "İyi insanlar sorumlu davranmak için yasalara ihtiyaç duymazlar; kötü insanlar ise yasaları aşmanın bir yolunu ararlar.", author: "Platon", source: "Devlet" },
  { text: "Müzik, evrene ruh, zihne kanat, hayal gücüne uçuş ve her şeye hayat verir.", author: "Platon", source: "Diyaloglar" },
  { text: "Karanlıktan korkan bir çocuğu kolayca affedebiliriz; hayatın gerçek trajedisi yetişkinlerin aydınlıktan korkmasıdır.", author: "Platon", source: "Devlet — Mağara Alegorisi Üzerine" },
  { text: "Biz sürekli olarak ne yapıyorsak oyuz. O halde mükemmellik bir eylem değil, bir alışkanlıktır.", author: "Aristoteles", source: "Nikomakhos'a Etik (Will Durant Özeti)" },
  { text: "Eğitimin kökleri acıdır, fakat meyvesi tatlıdır.", author: "Aristoteles", source: "Diogenes Laertios — Ünlü Filozofların Yaşamları" },
  { text: "Kendini bilmek, tüm bilgeliğin başlangıcıdır.", author: "Aristoteles", source: "Nikomakhos'a Etik" },
  { text: "Umut, uyanık insanın rüyasıdır.", author: "Aristoteles", source: "Diogenes Laertios, 5.18" },
  { text: "Mutluluk kendi kendimize yeterliliktir; bize bağlıdır.", author: "Aristoteles", source: "Nikomakhos'a Etik, 10. Kitap" },
  { text: "Eleştiriden kaçınmanın tek bir yolu vardır: Hiçbir şey yapmamak, hiçbir şey söylememek ve hiçbir şey olmamak.", author: "Aristoteles", source: "Retorik Üzerine" },
  { text: "Doğa hiçbir şeyi boşuna yapmaz.", author: "Aristoteles", source: "Politika, 1. Kitap" },
  { text: "Öfkelenmek kolaydır; ama doğru kişiye, doğru ölçüde, doğru zamanda, doğru amaçla ve doğru biçimde öfkelenmek kolay değildir.", author: "Aristoteles", source: "Nikomakhos'a Etik, 2. Kitap" },
  { text: "Aynı nehirde iki kez yıkanılmaz; çünkü ne o nehir aynı nehirdir, ne de o insan aynı insandır.", author: "Herakleitos", source: "Fragmanlar, B91" },
  { text: "Değişmeyen tek şey, değişimin kendisidir.", author: "Herakleitos", source: "Fragmanlar" },
  { text: "İnsanın karakteri, onun kaderidir.", author: "Herakleitos", source: "Fragmanlar, B119" },
  { text: "Çok şey bilmek akıllı olmayı öğretmez.", author: "Herakleitos", source: "Fragmanlar, B40" },
  { text: "Kitapsız bir oda, ruhsuz bir beden gibidir.", author: "Cicero", source: "Mektuplar ve Söylevler" },
  { text: "Nefes aldığım sürece umut ediyorum.", author: "Cicero", source: "Atticus'a Mektuplar, 9.10" },
  { text: "Şükran duygusu yalnızca en büyük erdem değil, diğer tüm erdemlerin de anasıdır.", author: "Cicero", source: "Pro Plancio, 80" },
  { text: "Tarih bilmeyen, her zaman çocuk kalmaya mahkûmdur.", author: "Cicero", source: "Orator, 120" },
  { text: "Günü yakala; yarına olabildiğince az güven.", author: "Horatius", source: "Odlar (Carmina), 1.11 (Carpe Diem)" },
  { text: "Su damlası taşı gücüyle değil, sık ve sürekli düşmesiyle deler.", author: "Ovidius", source: "Karadeniz'den Mektuplar (Epistulae ex Ponto)" },
  { text: "Başlayan iş, yarılanmış demektir; bilge olmaya cesaret et ve hemen başla.", author: "Horatius", source: "Mektuplar (Epistulae), 1.2" },
  { text: "Bana dayanacak bir nokta verin, dünyayı yerinden oynatayım.", author: "Arşimet", source: "Pappus — Synagoge" },
  { text: "Gölge etme, başka ihsan istemem.", author: "Diyojen", source: "Plutarkhos — Büyük İskender'in Hayatı" },
  { text: "İki kulağımız ve bir dilimiz vardır; daha çok dinleyip daha az konuşalım diye.", author: "Kıbrıslı Zenon", source: "Diogenes Laertios, 7.23" },
  { text: "Mutluluk, yaşamın iyi bir akışıdır.", author: "Kıbrıslı Zenon", source: "Stobaeus Aktarımı" },
  { text: "Cesurlara talih yardım eder.", author: "Vergilius", source: "Aeneis, 10.284" },
  { text: "Zorlukların içinden yıldızlara doğru.", author: "Seneca", source: "Hercules Furens (Per aspera ad astra)" },
  { text: "Az konuş, çok iş yap.", author: "Pisagor", source: "Altın Mısralar" },

  // 91 - 140: Anadolu, İslam ve Doğu Bilgeliği (Mevlânâ, Yunus Emre, İbn Haldun, İbn Sînâ, Fârâbî, Hacı Bektaş, Lao Tzu, Konfüçyüs)
  { text: "Dün akıllıydım, dünyayı değiştirmek istedim; bugün ise bilgeyim, kendimi değiştiriyorum.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Mesnevî / Fîhi Mâ Fîh" },
  { text: "Dünle beraber gitti cancağızım, ne kadar söz varsa düne ait; şimdi yeni şeyler söylemek lazım.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Dîvân-ı Kebîr" },
  { text: "Kusur arıyorsan, tüm aynalar senin.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Mesnevî" },
  { text: "Yola çıkınca yol görünür.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Mesnevî" },
  { text: "Ya olduğun gibi görün, ya göründüğün gibi ol.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Mesnevî" },
  { text: "Yara, ışığın içeri girdiği yerdir.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Mesnevî" },
  { text: "Sabır, boyun eğmek değil, mücadele etmektir; sabır, dikenin içinde gülü görmektir.", author: "Şems-i Tebrîzî", source: "Makâlât" },
  { text: "Sesini değil, sözünü yükselt; zira çiçekleri büyüten gök gürültüsü değil, yağmurdur.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Mesnevî" },
  { text: "Bir mum diğer bir mumu tutuşturmakla ışığından bir şey kaybetmez.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Fîhi Mâ Fîh" },
  { text: "İlim ilim bilmektir, ilim kendin bilmektir. Sen kendini bilmezsin, ya nice okumaktır.", author: "Yunus Emre", source: "Risâletü'n-Nushiyye / Divan" },
  { text: "Sevelim, sevilelim; dünya kimseye kalmaz.", author: "Yunus Emre", source: "Yunus Emre Divanı" },
  { text: "Cümleler doğrudur sen doğru isen, doğruluk bulunmaz sen eğri isen.", author: "Yunus Emre", source: "Risâletü'n-Nushiyye" },
  { text: "Bölüşürsek tok oluruz, bölünürsek yok oluruz.", author: "Yunus Emre", source: "Yunus Emre Divanı" },
  { text: "İncinsen de incitme.", author: "Hacı Bektaş Veli", source: "Makâlât" },
  { text: "Her ne ararsan kendinde ara.", author: "Hacı Bektaş Veli", source: "Makâlât" },
  { text: "Bilimden gidilmeyen yolun sonu karanlıktır.", author: "Hacı Bektaş Veli", source: "Velâyetnâme / Makâlât" },
  { text: "İnsanı yaşat ki devlet yaşasın.", author: "Şeyh Edebali", source: "Osman Gazi'ye Nasihat" },
  { text: "Geçmişi olmayanın geleceği olamaz; dünü unutma, bugünü iyi yaşa, yarına hazırlan.", author: "Şeyh Edebali", source: "Nasihatname" },
  { text: "İnsan alışkanlıklarının çocuğudur.", author: "İbn Haldun", source: "Mukaddime, 1. Cilt" },
  { text: "Coğrafya kaderdir.", author: "İbn Haldun", source: "Mukaddime" },
  { text: "Geçmişler geleceğe, suyun suya benzemesinden daha çok benzer.", author: "İbn Haldun", source: "Mukaddime" },
  { text: "Bilim ve sanat takdir edilmediği yerden göç eder.", author: "İbn Sînâ", source: "Kitâbü'ş-Şifâ / Risaleler" },
  { text: "Tıbbın görevi sadece hastalığı iyileştirmek değil, sağlığı da korumaktır.", author: "İbn Sînâ", source: "El-Kanun fi't-Tıb" },
  { text: "Hiçbir şey kendi kendine var olmaz; her sonucun bir nedeni ve her başarının bir çabası vardır.", author: "İbn Sînâ", source: "İşârât ve't-Tenbîhât" },
  { text: "Önce doğruyu bilmek gerekir; doğru bilinirse yanlış da bilinir, ama önce yanlış bilinirse doğruya ulaşılamaz.", author: "Fârâbî", source: "et-Tenbîh alâ Sebîli's-Saâde" },
  { text: "Erdemli toplum, insanların gerçek mutluluğa ulaşmak için yardımlaştıkları toplumdur.", author: "Fârâbî", source: "El-Medinetü'l-Fâzıla" },
  { text: "Bilgi, insanı şüphelerden kurtaran en sağlam ışıktır.", author: "Birûnî", source: "Tahdîdü Nihâyâti'l-Emâkin" },
  { text: "Meyvesiz ağaca kimse taş atmaz.", author: "Sa'dî-i Şîrâzî", source: "Gülistan" },
  { text: "Haksızlık karşısında eğilmeyiniz; çünkü hakkınızla beraber şerefinizi de kaybedersiniz.", author: "Hz. Ali", source: "Nehcü'l-Belâga" },
  { text: "Bin millik bir yolculuk tek bir adımla başlar.", author: "Lao Tzu", source: "Tao Te Ching, 64. Bölüm" },
  { text: "Başkalarını bilen kimse bilgili, kendini bilen kimse bilgedir. Başkalarını yenen güçlüdür, kendi nefsini yenen ise kudretlidir.", author: "Lao Tzu", source: "Tao Te Ching, 33. Bölüm" },
  { text: "Doğa acele etmez, yine de her şey zamanında tamamlanır.", author: "Lao Tzu", source: "Tao Te Ching" },
  { text: "Düşüncelerine dikkat et, sözlerine dönüşür; sözlerine dikkat et, eylemlerine dönüşür; eylemlerine dikkat et, alışkanlıklarına dönüşür; alışkanlıklarına dikkat et, karakterine dönüşür.", author: "Lao Tzu", source: "Doğu Bilgeliği Geleneği" },
  { text: "Ne kadar yavaş gittiğinin bir önemi yoktur, yeter ki durma.", author: "Konfüçyüs", source: "Konuşmalar (Analects)" },
  { text: "Hedefe ulaşamadığın belli olduğunda hedefini değiştirme; attığın adımları değiştir.", author: "Konfüçyüs", source: "Konuşmalar" },
  { text: "Duyarım ve unuturum. Görürüm ve hatırlarım. Yaparım ve anlarım.", author: "Konfüçyüs", source: "Xunzi / Konfüçyüs Geleneği" },
  { text: "Üç yolla bilgelik öğreniriz: Birincisi ve en soylusu derin düşünmedir; ikincisi ve en kolayı taklittir; üçüncüsü ve en acısı deneyimdir.", author: "Konfüçyüs", source: "Konuşmalar" },
  { text: "Dağı yerinden oynatan kişi, işe küçük taşları taşımakla başlayandır.", author: "Konfüçyüs", source: "Konuşmalar" },
  { text: "Karanlığa küfredeceğine bir mum yak.", author: "Konfüçyüs", source: "Doğu Atasözü / Konfüçyüs" },
  { text: "İnsanın iki hayatı vardır ve ikincisi, sadece bir hayatı olduğunu anladığında başlar.", author: "Konfüçyüs", source: "Bilgelik Yazıları" },
  { text: "Kendini ve düşmanını tanırsan, yüz savaşa da girsen tehlikeye düşmezsin.", author: "Sun Tzu", source: "Savaş Sanatı (The Art of War), 3. Bölüm" },
  { text: "Kaosun ortasında aynı zamanda fırsat da vardır.", author: "Sun Tzu", source: "Savaş Sanatı" },
  { text: "Stratejisiz taktik, yenilgi öncesi gürültüdür.", author: "Sun Tzu", source: "Savaş Sanatı" },
  { text: "Zihin her şeydir. Ne düşünürsen, o olursun.", author: "Buda", source: "Dhammapada, 1. Bölüm" },
  { text: "Sadece suya bakarak denizi geçemezsin.", author: "Rabindranath Tagore", source: "Sadhana / Şiirler" },
  { text: "Güneşi kaçırdım diye ağlarsan, yıldızları da göremezsin.", author: "Rabindranath Tagore", source: "Aforizmalar (Stray Birds)" },
  { text: "Kökleri toprağın derinliklerinde olan ağaç, dallarına çarpan fırtınadan korkmaz.", author: "Halil Cibran", source: "Ermiş (The Prophet)" },
  { text: "Çalışmak, görünür kılınmış sevgidir.", author: "Halil Cibran", source: "Ermiş" },
  { text: "Biraz bilgi ve onu uygulamak, çok bilgiye sahip olup hiçbir şey yapmamaktan çok daha değerlidir.", author: "Halil Cibran", source: "Ermiş" },
  { text: "Acıların içinden en güçlü ruhlar çıkar; en sağlam karakterler yara izleriyle kaplıdır.", author: "Halil Cibran", source: "Kırık Kanatlar" },

  // 141 - 200: Türk Edebiyatı ve Düşünce Dünyası (Cemil Meriç, Doğan Cüceloğlu, Nâzım Hikmet, Sabahattin Ali, Yaşar Kemal, Tanpınar, Oğuz Atay, vb.)
  { text: "Kitap, zekâyı kibarlaştırır.", author: "Cemil Meriç", source: "Bu Ülke" },
  { text: "İnsanlar sevilmek için yaratıldılar, eşyalar ise kullanılmak için. Dünyadaki kaosun nedeni; eşyaların sevilmeleri ve insanların kullanılmalarıdır.", author: "Cemil Meriç", source: "Jurnal" },
  { text: "Kamus, bir milletin hafızasıdır; heyecanıyla, hassasiyetiyle, şuuruyla.", author: "Cemil Meriç", source: "Bu Ülke" },
  { text: "İzm'ler idrakimize giydirilen deli gömlekleridir.", author: "Cemil Meriç", source: "Bu Ülke" },
  { text: "Aydın olmak için önce insan olmak lazımdır.", author: "Cemil Meriç", source: "Mağaradakiler" },
  { text: "Niyetiniz ne ise, geleceğiniz odur. İnsan kendi yaşamının sorumluluğunu aldığı gün büyür.", author: "Doğan Cüceloğlu", source: "Savaşçı" },
  { text: "Çocuğun ana-babasından öğrendiği en önemli şey, hayatın zorlukları karşısında nasıl duracağıdır.", author: "Doğan Cüceloğlu", source: "Geliştiren Anne-Baba" },
  { text: "Gerçek özgürlük, insanın kendi değerlerinin farkında olması ve o değerler doğrultusunda seçim yapabilmesidir.", author: "Doğan Cüceloğlu", source: "İçimizdeki Biz" },
  { text: "İletişim, karşımızdakini değiştirmek için değil, anlamak için kurulduğunda iyileştirir.", author: "Doğan Cüceloğlu", source: "Yeniden İnsan İnsana" },
  { text: "Yaşamak şakaya gelmez, büyük bir ciddiyetle yaşayacaksın bir sincap gibi mesela; yani, yaşamanın dışında ve ötesinde hiçbir şey beklemeden.", author: "Nâzım Hikmet", source: "Yaşamak Üzerine (1947)" },
  { text: "Yaşamak bir ağaç gibi tek ve hür ve bir orman gibi kardeşçesine, bu hasret bizim.", author: "Nâzım Hikmet", source: "Davet" },
  { text: "En güzel deniz: henüz gidilmemiş olanıdır. En güzel çocuk: henüz büyümedi. En güzel günlerimiz: henüz yaşamadıklarımız.", author: "Nâzım Hikmet", source: "Benerci Kendini Niçin Öldürdü / Şiirler" },
  { text: "Sen yanmazsan, ben yanmazsam, biz yanmazsak, nasıl çıkar karanlıklar aydınlığa?", author: "Nâzım Hikmet", source: "Kerem Gibi (1930)" },
  { text: "Dünyada bir insana diğer bir insanın verebileceği en kıymetli şey, samimi bir anlayıştır.", author: "Sabahattin Ali", source: "Kürk Mantolu Madonna" },
  { text: "İnsanın iç dünyası ne kadar zengin olursa, dış dünyaya o kadar az muhtaç olur.", author: "Sabahattin Ali", source: "İçimizdeki Şeytan" },
  { text: "Hayatta hiçbir zaman kafamızdaki kadar harikulade şeyler olmayacağını henüz idrak etmemiştim.", author: "Sabahattin Ali", source: "Kürk Mantolu Madonna" },
  { text: "İyilik demek, kimseye kötülüğü dokunmamak değil, kötülük yapacak cevheri içinde taşımamak demektir.", author: "Sabahattin Ali", source: "Kuyucaklı Yusuf" },
  { text: "İnsan evrende gövdesi kadar değil, yüreği kadar yer kaplar.", author: "Yaşar Kemal", source: "İnce Memed" },
  { text: "Zulfinin teline bağlamışlar dünyayı, umut ettikçe insan yaşar.", author: "Yaşar Kemal", source: "Demirciler Çarşısı Cinayeti" },
  { text: "Dağlar, insanlar ve hatta ölüm bile yorulduysa, şimdi en güzel şiir barıştır.", author: "Yaşar Kemal", source: "Röportajlar ve Denemeler" },
  { text: "İnsanın en büyük düşmanı, kendi içindeki korkusudur.", author: "Yaşar Kemal", source: "Ortadirek" },
  { text: "Türkiye'nin evlatları kendilerinden başka hiçbir şeyin etrafında toplanamazlar; çalışmak ve zaman kavramına sahip olmak zorundayız.", author: "Ahmet Hamdi Tanpınar", source: "Beş Şehir / Saatleri Ayarlama Enstitüsü" },
  { text: "İnsan, kendi zamanının mimarı oldukça huzur bulur.", author: "Ahmet Hamdi Tanpınar", source: "Huzur" },
  { text: "Sanat, insanın zamana karşı kazandığı en soylu zaferdir.", author: "Ahmet Hamdi Tanpınar", source: "Edebiyat Üzerine Makaleler" },
  { text: "Ben buradayım sevgili okuyucum, sen neredesin acaba?", author: "Oğuz Atay", source: "Korkuyu Beklerken" },
  { text: "İnsan alışkanlıklarıyla değil, kendisiyle yüzleşebildiği ölçüde gerçektir.", author: "Oğuz Atay", source: "Tutunamayanlar" },
  { text: "Kelimeler albayım, bazı anlamlara gelmiyor.", author: "Oğuz Atay", source: "Tehlikeli Oyunlar" },
  { text: "Kendime yeni bir hayat kurmak için önce eski bahanelerimi bırakmam gerekiyordu.", author: "Oğuz Atay", source: "Günlük" },
  { text: "Bir kitabın sayfaları arasında kendi sesini bulduğunda artık yalnız değilsindir.", author: "Peyami Safa", source: "Dokuzuncu Hariciye Koğuşu" },
  { text: "Şüphe, hakikate giden yolun ilk basamağıdır.", author: "Peyami Safa", source: "Yalnızız" },
  { text: "Kendi kendine yetmeyi öğrenen ruh, dışarıdaki fırtınalardan sarsılmaz.", author: "Halide Edib Adıvar", source: "Ateşten Gömlek / Sinekli Bakkal" },
  { text: "Memleket isterim: Gök mavi, dal yeşil, tarla sarı olsun; kuşların çiçeklerin diyarı olsun.", author: "Cahit Sıtkı Tarancı", source: "Memleket İsterim" },
  { text: "Yaş otuz beş! Yolun yarısı eder. Dante gibi ortasındayız ömrün.", author: "Cahit Sıtkı Tarancı", source: "Otuz Beş Yaş" },
  { text: "Bütün kusurumuzu toprak gizliyor; merhem çalıp yaralarım düzlüyor.", author: "Âşık Veysel", source: "Kara Toprak" },
  { text: "Uzun ince bir yoldayım, gidiyorum gündüz gece.", author: "Âşık Veysel", source: "Dostlar Beni Hatırlasın" },
  { text: "Güzelliğin on par'etmez, bu bendeki aşk olmasa.", author: "Âşık Veysel", source: "Deyişler" },
  { text: "Yalnızlık dışarıdan gelmez, insanın içindedir.", author: "Özdemir Asaf", source: "Yuvarlağın Köşeleri" },
  { text: "Bütün renkler aynı hızla kirleniyordu, birinciliği beyaza verdiler.", author: "Özdemir Asaf", source: "Çiçek Senfonisi" },
  { text: "Sözün bilgisi, kılıcın keskinliğinden üstündür.", author: "Yusuf Has Hâcib", source: "Kutadgu Bilig" },
  { text: "Bilgi, bilgisiz için karanlıkta yanan bir meşaledir.", author: "Yusuf Has Hâcib", source: "Kutadgu Bilig" },
  { text: "Dil, aklın ve bilginin tercümanıdır.", author: "Kaşgarlı Mahmud", source: "Dîvânu Lugâti't-Türk" },
  { text: "Tomurcuk derdinde olmayan ağaç, odundur.", author: "Necip Fazıl Kısakürek", source: "Çile" },
  { text: "Devler gibi eserler bırakmak için, karıncalar gibi çalışmak lazım.", author: "Necip Fazıl Kısakürek", source: "Hitabe ve Yazılar" },
  { text: "Allah bu millete bir daha İstiklâl Marşı yazdırmasın.", author: "Mehmet Akif Ersoy", source: "Safahat / Hatıralar" },
  { text: "Sözüm odun gibi olsun, hakikat olsun tek!", author: "Mehmet Akif Ersoy", source: "Safahat" },
  { text: "Atiyi karanlık görerek azmi bırakmak, alçak bir ölüm varsa, eminim, budur ancak.", author: "Mehmet Akif Ersoy", source: "Safahat — Yeis" },
  { text: "İnsanın vatanı, çocukluğudur.", author: "Cemal Süreya", source: "Günler (99 Yüz)" },
  { text: "Hayat kısa, kuşlar uçuyor.", author: "Cemal Süreya", source: "Sevda Sözleri" },
  { text: "Ben senin en çok bana yansıyan yanını sevdim.", author: "Özdemir Asaf", source: "Lavinia" },
  { text: "Gökyüzü gibi bir şey bu çocukluk, hiçbir yere gitmiyor.", author: "Edip Cansever", source: "Bezik Oynayan Kadınlar" },
  { text: "İnsan yaşadığı yere benzer; o yerin suyuna, o yerin toprağına benzer.", author: "Edip Cansever", source: "Mendilimde Kan Sesleri" },
  { text: "Kursağında kalan her heves, zamanla hayat felsefene dönüşür.", author: "Turgut Uyar", source: "Büyük Saat" },
  { text: "Burası dünya! Ne çok kıymetlendirdik; oysa bir tarla idi, ekip biçip gidecektik.", author: "Cahit Zarifoğlu", source: "Yaşamak" },
  { text: "Güzel günler göreceğiz çocuklar, güneşli günler göreceğiz.", author: "Nâzım Hikmet", source: "Nikbinlik" },
  { text: "Bir insanı sevmekle başlar her şey.", author: "Sait Faik Abasıyanık", source: "Alemdağ'da Var Bir Yılan" },
  { text: "Yazmasam deli olacaktım.", author: "Sait Faik Abasıyanık", source: "Haritada Bir Nokta" },
  { text: "Zaman, kendisine değer verenlerin dostudur.", author: "Hasan Âli Yücel", source: "İyi Vatandaş İyi İnsan" },
  { text: "Okumak, insanı kendi dar dünyasından çıkarıp bütün insanlığın tecrübesine ortak eder.", author: "Nurettin Topçu", source: "Türkiye'nin Maarif Davası" },
  { text: "İrade, insanın kendi kaderine vurduğu mühürdür.", author: "Nurettin Topçu", source: "İsyan Ahlakı" },
  { text: "Bilim, gerçeği aramanın en dürüst yoludur.", author: "Cahit Arf", source: "Üniversite Konuşmaları" },

  // 201 - 260: Avrupa Felsefesi ve Edebiyatı (Montaigne, Goethe, Nietzsche, Schopenhauer, Kant, Spinoza, Voltaire, Hugo, Camus, Zweig, Kafka, Hesse)
  { text: "Hedefi olmayan gemiye hiçbir rüzgâr yardım etmez.", author: "Michel de Montaigne", source: "Denemeler (Essais)" },
  { text: "Hayatımın en güzel eseri, onu doğru yaşamaktır.", author: "Michel de Montaigne", source: "Denemeler, 3. Kitap, 13. Bölüm" },
  { text: "Korktuğum şeylerin çoğu hiçbir zaman başıma gelmedi.", author: "Michel de Montaigne", source: "Denemeler" },
  { text: "Bir insanın gerçek değeri, yalnız kaldığında ne düşündüğü ve ne yaptığıyla ölçülür.", author: "Michel de Montaigne", source: "Denemeler, 1. Kitap" },
  { text: "Bilmek yetmez, uygulamak gerekir. İstemek yetmez, yapmak gerekir.", author: "Johann Wolfgang von Goethe", source: "Wilhelm Meister'in Çıraklık Yılları" },
  { text: "Kişi her gün en az bir küçük şarkı dinlemeli, iyi bir şiir okumalı, güzel bir resme bakmalı ve mümkünse birkaç mantıklı söz söylemelidir.", author: "Johann Wolfgang von Goethe", source: "Wilhelm Meister'in Çıraklık Yılları" },
  { text: "En önemli şeylerin, en önemsiz şeylerin insafına kalmasına asla izin verme.", author: "Johann Wolfgang von Goethe", source: "Özdeyişler ve Yansımalar" },
  { text: "Neye inanırsan ve neyi tutkuyla başarmaya başlarsan, cesaretin içinde deha, güç ve sihir barındırır.", author: "Johann Wolfgang von Goethe", source: "Faust" },
  { text: "İnsanın karakteri, elinde güç varken zayıflara nasıl davrandığından belli olur.", author: "Johann Wolfgang von Goethe", source: "Maximen und Reflexionen" },
  { text: "Yaşamak için bir 'neden'i olan insan, hemen her 'nasıl'a katlanabilir.", author: "Friedrich Nietzsche", source: "Putların Alacakaranlığı, Özdeyiş 12" },
  { text: "Beni öldürmeyen şey, beni daha güçlü kılar.", author: "Friedrich Nietzsche", source: "Putların Alacakaranlığı, Özdeyiş 8" },
  { text: "Dans eden bir yıldız doğurmak için insanın içinde kaos olması gerekir.", author: "Friedrich Nietzsche", source: "Böyle Buyurdu Zerdüşt" },
  { text: "Uçmayı öğrenmek isteyen, önce ayakta durmayı, yürümeyi, koşmayı ve tırmanmayı öğrenmelidir; insan bir anda uçamaz.", author: "Friedrich Nietzsche", source: "Böyle Buyurdu Zerdüşt" },
  { text: "Derisini değiştirmeyen yılan ölmeye mahkûmdur; düşüncelerini yenileyemeyen zihinler de öyle.", author: "Friedrich Nietzsche", source: "Tan Kızıllığı (Daybreak)" },
  { text: "Müzik olmadan hayat bir hata olurdu.", author: "Friedrich Nietzsche", source: "Putların Alacakaranlığı" },
  { text: "Yükseldikçe, uçmayı bilmeyenlere daha küçük görünürüz.", author: "Friedrich Nietzsche", source: "Böyle Buyurdu Zerdüşt" },
  { text: "Her insan, kendi görüş alanının sınırlarını dünyanın sınırları sanır.", author: "Arthur Schopenhauer", source: "Parerga ve Paralipomena" },
  { text: "Yetenek kimsenin vuramadığı hedefi vurur; deha ise kimsenin göremediği hedefi vurur.", author: "Arthur Schopenhauer", source: "İrade ve Tasarım Olarak Dünya" },
  { text: "Sağlık her şey değildir, ama sağlık olmadan her şey bir hiçtir.", author: "Arthur Schopenhauer", source: "Yaşam Bilgeliği Üzerine Aforizmalar" },
  { text: "Kendi aklını kullanma cesaretini göster! (Sapere aude!)", author: "Immanuel Kant", source: "Aydınlanma Nedir? (1784)" },
  { text: "İki şey ruhumu her düşündüğümde hep yeni ve artan bir hayranlıkla doldurur: Üzerimdeki yıldızlı gökyüzü ve içimdeki ahlak yasası.", author: "Immanuel Kant", source: "Pratik Aklın Eleştirisi" },
  { text: "Bilim organize edilmiş bilgidir; bilgelik ise organize edilmiş yaşamdır.", author: "Immanuel Kant", source: "Felsefe Dersleri" },
  { text: "Ağlama, öfkelenme; anlamaya çalış.", author: "Baruch Spinoza", source: "Politik İnceleme (Tractatus Politicus), 1.4" },
  { text: "Mükemmel olan her şey, nadir olduğu kadar zordur da.", author: "Baruch Spinoza", source: "Etika (Ethica), 5. Bölümün Son Sözü" },
  { text: "Düşünüyorum, öyleyse varım.", author: "René Descartes", source: "Yöntem Üzerine Konuşma (1637)" },
  { text: "İyi bir zihne sahip olmak yetmez; asıl mesele onu iyi kullanmaktır.", author: "René Descartes", source: "Yöntem Üzerine Konuşma" },
  { text: "İnsanların bütün mutsuzluğu tek bir şeyden kaynaklanır: Bir odada sessizce oturmayı bilmemelerinden.", author: "Blaise Pascal", source: "Düşünceler (Pensées), 139" },
  { text: "Kalbin, aklın hiç bilmediği kendine has nedenleri vardır.", author: "Blaise Pascal", source: "Düşünceler, 277" },
  { text: "İnsan sadece düşünen bir sazdır; doğadaki en zayıf varlıktır ama düşünen bir sazdır.", author: "Blaise Pascal", source: "Düşünceler, 347" },
  { text: "Kendi bahçemizi yetiştirmeliyiz.", author: "Voltaire", source: "Candide (Son Cümle)" },
  { text: "Mükemmel, iyinin düşmanıdır.", author: "Voltaire", source: "Felsefe Sözlüğü (Dictionnaire Philosophique)" },
  { text: "Bir insanı verdiği cevaplardan değil, sorduğu sorulardan değerlendir.", author: "Voltaire", source: "Mektuplar ve Denemeler" },
  { text: "Sabır acıdır, ama meyvesi tatlıdır.", author: "Jean-Jacques Rousseau", source: "Émile ya da Eğitim Üzerine" },
  { text: "Hiçbir şey, zamanı gelmiş bir fikirden daha güçlü değildir.", author: "Victor Hugo", source: "Bir Suçun Tarihi (Histoire d'un Crime)" },
  { text: "Bir okul açan, bir hapishane kapatır.", author: "Victor Hugo", source: "Eğitim Üzerine Konuşmalar" },
  { text: "En karanlık gece bile sona erer ve güneş tekrar doğar.", author: "Victor Hugo", source: "Sefiller (Les Misérables)" },
  { text: "Azim, imkânsızı mümkün, mümkünü kolay, kolayı da zarif kılar.", author: "Honoré de Balzac", source: "İnsanlık Komedyası" },
  { text: "Kışın tam ortasında, içimde yenilmez bir yaz olduğunu öğrendim.", author: "Albert Camus", source: "Yaz (L'Été — Tipasa'ya Dönüş, 1954)" },
  { text: "Zirveye doğru verilen mücadelenin kendisi bile bir insanın kalbini doldurmaya yeter.", author: "Albert Camus", source: "Sisifos Söyleni" },
  { text: "Gerçek cömertlik, geleceğe karşı her şeyi bugüne vermekten ibarettir.", author: "Albert Camus", source: "Başkaldıran İnsan" },
  { text: "Özgürlük, insanın kendisine yapılanlarla ne yaptığıdır.", author: "Jean-Paul Sartre", source: "Varlık ve Hiçlik Üzerine" },
  { text: "Hiçbir şey kendiliğinden büyük olmaz; onu büyük yapan senin ona verdiğin emektir.", author: "Antoine de Saint-Exupéry", source: "Küçük Prens" },
  { text: "Gözler kördür; insan ancak yüreğiyle baktığında gerçeği görebilir.", author: "Antoine de Saint-Exupéry", source: "Küçük Prens" },
  { text: "Planı olmayan bir hedef, sadece bir dilektir.", author: "Antoine de Saint-Exupéry", source: "Kale (Citadelle)" },
  { text: "Bir gemi inşa etmek istiyorsan, insanları odun toplamaya zorlama; onlara uçsuz bucaksız denizin özlemini öğret.", author: "Antoine de Saint-Exupéry", source: "Kale" },
  { text: "İnsan kendi kanatlarının ağırlığını ancak uçmaya başladığında unutur.", author: "Stefan Zweig", source: "İnsanlığın Yıldızının Parladığı Anlar" },
  { text: "Hiçbir şey ruhu, büyük bir amaca hizmet etmek kadar yükseltmez.", author: "Stefan Zweig", source: "Dünün Dünyası" },
  { text: "Bir kitap, içimizdeki donmuş denizi kıran bir balta olmalıdır.", author: "Franz Kafka", source: "Oskar Pollak'a Mektup (27 Ocak 1904)" },
  { text: "Yollar yürümekle ortaya çıkar.", author: "Franz Kafka", source: "Aforizmalar" },
  { text: "Kuş, yumurtadan çıkmak için savaşır. Yumurta dünyadır. Doğmak isteyen, bir dünyayı yıkmak zorundadır.", author: "Hermann Hesse", source: "Demian" },
  { text: "Bazılarımız tutunmanın bizi güçlü kıldığını düşünür; oysa bazen asıl güç, bırakabilmektir.", author: "Hermann Hesse", source: "Siddhartha" },
  { text: "Bilgelik başkasına aktarılamaz; bilgelik ancak insanın kendi yolculuğunda deneyimlenebilir.", author: "Hermann Hesse", source: "Siddhartha" },
  { text: "Sabırla bütün sorularını yaşamaya çalış; belki bir gün farkına bile varmadan cevapların içine doğru yaşadığını göreceksin.", author: "Rainer Maria Rilke", source: "Genç Bir Şaire Mektuplar, 4. Mektup" },
  { text: "Yeni bir adım atmak, yeni bir söz söylemek insanların en çok korktuğu şeydir.", author: "Fyodor Dostoyevski", source: "Suç ve Ceza" },
  { text: "Ruhu iyileştiren şey, çocuklarla vakit geçirmek ve dürüst kalmaktır.", author: "Fyodor Dostoyevski", source: "Budala" },
  { text: "Acı ve keder, büyük bir bilincin ve derin bir yüreğin her zaman ayrılmaz parçasıdır.", author: "Fyodor Dostoyevski", source: "Suç ve Ceza" },
  { text: "En güçlü iki savaşçı sabır ve zamandır.", author: "Lev Tolstoy", source: "Savaş ve Barış" },
  { text: "Herkes dünyayı değiştirmeyi düşünür, ama kimse kendini değiştirmeyi düşünmez.", author: "Lev Tolstoy", source: "Üç Soru / Düşünceler" },
  { text: "Mutlu ailelerin hepsi birbirine benzer; her mutsuz ailenin ise kendine özgü bir mutsuzluğu vardır.", author: "Lev Tolstoy", source: "Anna Karenina" },
  { text: "En önemli zaman şu andır; en önemli kişi şu an yanında olandır; en önemli iş ise iyilik yapmaktır.", author: "Lev Tolstoy", source: "Üç Soru" },

  // 261 - 315: İngiliz, İrlanda ve Dünya Edebiyatı Klasikleri (Shakespeare, Bacon, Wilde, Shaw, Woolf, Orwell, Márquez, Borges, Cervantes, Dante)
  { text: "Kendi özüne sadık kal; o zaman gece gündüzü nasıl takip ederse, sen de kimseye karşı sahte olmazsın.", author: "William Shakespeare", source: "Hamlet, 1. Perde, 3. Sahne" },
  { text: "Şüphelerimiz haindir; denemekten korktuğumuz için kazanabileceğimiz iyilikleri bize kaybettirirler.", author: "William Shakespeare", source: "Kısasa Kısas (Measure for Measure)" },
  { text: "Ne olduğumuzu biliyoruz ama ne olabileceğimizi henüz bilmiyoruz.", author: "William Shakespeare", source: "Hamlet, 4. Perde, 5. Sahne" },
  { text: "Kaderimiz yıldızlarda değil, kendi ellerimizdedir.", author: "William Shakespeare", source: "Julius Caesar, 1. Perde, 2. Sahne" },
  { text: "Üç saat erken gelmek, bir dakika geç kalmaktan her zaman daha iyidir.", author: "William Shakespeare", source: "Windsor'un Şen Kadınları" },
  { text: "Bilgi güçtür. (Scientia potentia est.)", author: "Francis Bacon", source: "Meditationes Sacrae (1597)" },
  { text: "Okumak insanı doldurur, tartışmak hazırlar, yazmak ise tam ve kesin kılar.", author: "Francis Bacon", source: "Denemeler — Çalışmalar Üzerine (Of Studies)" },
  { text: "Akıllı bir insan, bulduğundan daha fazla fırsat yaratır.", author: "Francis Bacon", source: "Bilimin İlerlemesi (The Advancement of Learning)" },
  { text: "Kendin ol; diğer herkes zaten kapılmış durumda.", author: "Oscar Wilde", source: "Özdeyişler" },
  { text: "Hepimiz çukurdayız, ama bazılarımız yıldızlara bakıyor.", author: "Oscar Wilde", source: "Lady Windermere'in Yelpazesi" },
  { text: "Deneyim, herkesin kendi hatalarına verdiği isimdir.", author: "Oscar Wilde", source: "Lady Windermere'in Yelpazesi" },
  { text: "Hayat kendini bulmakla ilgili değildir; hayat kendini yaratmakla ilgilidir.", author: "George Bernard Shaw", source: "Oyunlar ve Önsözler" },
  { text: "İlerleme değişim olmadan imkânsızdır; düşüncelerini değiştiremeyenler hiçbir şeyi değiştiremezler.", author: "George Bernard Shaw", source: "Everybody's Political What's What" },
  { text: "İletişimdeki en büyük yanılgı, iletişimin gerçekleştiğini sanmaktır.", author: "George Bernard Shaw", source: "Konuşmalar" },
  { text: "Zihnin önüne hiçbir kilit, hiçbir sürgü, hiçbir kapı koyamazsınız.", author: "Virginia Woolf", source: "Kendine Ait Bir Oda (1929)" },
  { text: "İnsan iyi yemek yemeden, iyi uyumadan, iyi düşünemez ve iyi sevemez.", author: "Virginia Woolf", source: "Kendine Ait Bir Oda" },
  { text: "Geçmişi kontrol eden geleceği kontrol eder; bugünü kontrol eden ise geçmişi kontrol eder.", author: "George Orwell", source: "1984" },
  { text: "Aldatmanın evrensel olduğu bir çağda, gerçeği söylemek devrimci bir eylemdir.", author: "George Orwell", source: "Siyasi Denemeler" },
  { text: "Gerçekler, onları görmezden geldiğinizde var olmaktan vazgeçmezler.", author: "Aldous Huxley", source: "Proper Studies (1927)" },
  { text: "Deneyim, bir insanın başına gelen şey değil; başına gelen şeyle ne yaptığıdır.", author: "Aldous Huxley", source: "Texts and Pretexts (1932)" },
  { text: "Zamanların en iyisiydi, zamanların en kötüsüydü; bilgelik çağıydı, yanılgı çağıydı.", author: "Charles Dickens", source: "İki Şehrin Hikâyesi" },
  { text: "Bu dünyada başkalarının yükünü hafifleten hiç kimse gereksiz değildir.", author: "Charles Dickens", source: "Doctor Marigold" },
  { text: "Dünyanın bütün problemi; akılsız ve fanatik insanların kendilerinden son derece emin olması, bilge insanların ise şüphelerle dolu olmasıdır.", author: "Bertrand Russell", source: "Aptallığın Zaferi (1933)" },
  { text: "Boşa harcamaktan keyif aldığınız zaman, boşa harcanmış zaman değildir.", author: "Bertrand Russell", source: "Mutluluk Yolu" },
  { text: "İyi yaşam, sevgiyle esinlenen ve bilgiyle yönlendirilen yaşamdır.", author: "Bertrand Russell", source: "Neye İnanıyorum (What I Believe)" },
  { text: "Hayat, insanın yaşadığı günler değil, hatırladığı ve nasıl hatırladığı günlerdir.", author: "Gabriel García Márquez", source: "Anlatmak İçin Yaşamak" },
  { text: "İnsanlar yaşlandıkları için hayallerinin peşinden koşmayı bırakmazlar; hayallerinin peşinden koşmayı bıraktıkları için yaşlanırlar.", author: "Gabriel García Márquez", source: "Yüzyıllık Yalnızlık / Röportajlar" },
  { text: "Cenneti her zaman bir tür kütüphane olarak hayal etmişimdir.", author: "Jorge Luis Borges", source: "Yetenekler Hakkında Şiir" },
  { text: "Şüphe, zekânın en samimi isimlerinden biridir.", author: "Jorge Luis Borges", source: "Soruşturmalar (Inquisiciones)" },
  { text: "Çok okuyan ve çok yürüyen insan, çok görür ve çok bilir.", author: "Miguel de Cervantes", source: "Don Kişot, 2. Bölüm, 25. Kısım" },
  { text: "Hazırlıklı olmak, zaferin yarısıdır.", author: "Miguel de Cervantes", source: "Don Kişot" },
  { text: "Kendi yıldızını takip etersen, görkemli limana ulaşmaktan asla geri kalmazsın.", author: "Dante Alighieri", source: "İlahi Komedya — Cehennem, 15. Kanto" },
  { text: "Cehennemin en karanlık yerleri, ahlaki kriz zamanlarında tarafsız kalanlara ayrılmıştır.", author: "Dante Alighieri", source: "İlahi Komedya — Cehennem, 3. Kanto" },
  { text: "Fırtına ne kadar sert eserse essin, sağlam kayadan ancak toz alır.", author: "Amin Maalouf", source: "Semerkant" },
  { text: "Bir şeye sahip olmak isteyen insan, önce o şeye layık olacak sabrı göstermelidir.", author: "Amin Maalouf", source: "Afrikalı Leo" },
  { text: "İyi bir okur, tek bir ömür yerine binlerce ömür yaşar; hiç okumayan ise yalnızca bir ömür yaşar.", author: "Umberto Eco", source: "Gülün Adı / Anlatı Ormanlarında Altı Gezinti" },
  { text: "Klasik, söyleyeceklerini hiçbir zaman tüketmeyen kitaptır.", author: "Italo Calvino", source: "Klasikleri Niçin Okumalıyız? (1991)" },
  { text: "Ağırlıktan kurtulmak, ciddiyetsizlik değil; dünyaya daha yüksek bir açıdan bakabilme berraklığıdır.", author: "Italo Calvino", source: "Amerika Dersleri" },
  { text: "Yaşam bir prova değildir; perde çoktan açıldı ve sahnedesin.", author: "Milan Kundera", source: "Varolmanın Dayanılmaz Hafifliği" },
  { text: "İnsanın gücü, kendi zaaflarını tanıyabilme cesaretinde saklıdır.", author: "Anton Çehov", source: "Vanya Dayı / Mektuplar" },
  { text: "Bilim insanın kendi haddini bilmesi ve sürekli araştırmasıdır.", author: "Anton Çehov", source: "Not Defterleri" },
  { text: "İnsanda her şey güzel olmalıdır: yüzü de, giysisi de, ruhu da, düşünceleri de.", author: "Anton Çehov", source: "Vanya Dayı, 2. Perde" },

  // 316 - 370: Bilim, Psikoloji, Sanat ve Modern Dünyanın Devleri (Einstein, Curie, Feynman, Pasteur, Sagan, Da Vinci, Frankl, Jung, Lincoln, Franklin, Twain, Hemingway)
  { text: "Zorlukların tam ortasında fırsatlar yatar.", author: "Albert Einstein", source: "Yazılar ve Mektuplar" },
  { text: "Hayal gücü bilgiden daha önemlidir. Çünkü bilgi sınırlıdır, hayal gücü ise tüm dünyayı kucaklar.", author: "Albert Einstein", source: "Saturday Evening Post Röportajı (1929)" },
  { text: "Hayat bisiklete binmek gibidir. Dengenizi korumak için hareket etmeye devam etmelisiniz.", author: "Albert Einstein", source: "Oğlu Eduard'a Mektup (5 Şubat 1930)" },
  { text: "Hiç hata yapmamış bir insan, yeni hiçbir şey denememiş demektir.", author: "Albert Einstein", source: "Konuşmalar ve Yazılar" },
  { text: "Önemli olan sorgulamayı bırakmamaktır. Merakın kendine ait bir varoluş nedeni vardır.", author: "Albert Einstein", source: "Life Dergisi (2 Mayıs 1955)" },
  { text: "Başarılı bir insan olmaya değil, değerli bir insan olmaya çalışın.", author: "Albert Einstein", source: "Life Dergisi (1955)" },
  { text: "Bir şeyi basitçe açıklayamıyorsanız, onu yeterince iyi anlamamışsınız demektir.", author: "Albert Einstein", source: "Bilim Yazıları" },
  { text: "Hayatta hiçbir şeyden korkulmamalıdır, sadece anlaşılmalıdır. Şimdi daha çok anlama zamanıdır ki daha az korkalım.", author: "Marie Curie", source: "Otobiyografik Notlar" },
  { text: "İnsanlar konusunda daha az, fikirler konusunda daha çok meraklı olun.", author: "Marie Curie", source: "Madame Curie Biyografisi (Ève Curie)" },
  { text: "Yolun kolay ve hızlı olduğunu bize kimse söylemedi; ama azimle yüründüğünde hedefe varıldığını biliyoruz.", author: "Marie Curie", source: "Laboratuvar Notları" },
  { text: "Birinci ilke şudur: Kendinizi kandırmamalısınız ve kandırılması en kolay kişi kendinizsiniz.", author: "Richard Feynman", source: "Cargo Cult Science (1974 Caltech Konuşması)" },
  { text: "Bir şeyin adını bilmek ile o şeyin ne olduğunu bilmek arasında büyük bir fark vardır.", author: "Richard Feynman", source: "Keşfetme Hazları (The Pleasure of Finding Things Out)" },
  { text: "Şans, yalnızca hazırlıklı zihinlere güler.", author: "Louis Pasteur", source: "Lille Üniversitesi Açılış Konuşması (7 Aralık 1854)" },
  { text: "Daha uzağı görebildiysem, bu devlerin omuzlarında durduğum içindir.", author: "Isaac Newton", source: "Robert Hooke'a Mektup (5 Şubat 1675)" },
  { text: "Bir insana hiçbir şey öğretemezsiniz; yalnızca onu kendi içinde keşfetmesine yardımcı olabilirsiniz.", author: "Galileo Galilei", source: "Diyaloglar" },
  { text: "Ölçülebileni ölç, ölçülemeyeni ise ölçülebilir hale getir.", author: "Galileo Galilei", source: "Bilim Yöntemi Üzerine" },
  { text: "Bir yerlerde inanılmaz bir şeyler keşfedilmeyi bekliyor.", author: "Carl Sagan", source: "Kozmos (Cosmos)" },
  { text: "Olağanüstü iddialar, olağanüstü kanıtlar gerektirir.", author: "Carl Sagan", source: "Kozmos (1980)" },
  { text: "Bizler, evrenin kendi kendisini tanımasının bir yoluyuz.", author: "Carl Sagan", source: "Kozmos, 1. Bölüm" },
  { text: "Ayaklarınıza değil, yıldızlara bakmayı unutmayın. Merakınızı asla kaybetmeyin.", author: "Stephen Hawking", source: "Büyük Sorulara Kısa Yanıtlar" },
  { text: "Zekâ, değişime uyum sağlayabilme yeteneğidir.", author: "Stephen Hawking", source: "Oxford Mezuniyet Konuşması" },
  { text: "Öğrenmek zihni asla yormaz.", author: "Leonardo da Vinci", source: "Defterler (Codex Atlanticus)" },
  { text: "Sadelik, gelişmişliğin en üst noktasıdır.", author: "Leonardo da Vinci", source: "Sanat ve Bilim Defterleri" },
  { text: "Demir kullanılmadığında paslanır, durgun su berraklığını yitirir; tembellik de zihnin gücünü öyle kemirir.", author: "Leonardo da Vinci", source: "Defterler" },
  { text: "İyi geçirilmiş bir gün nasıl mutlu bir uyku getirirse, iyi kullanılmış bir ömür de huzur getirir.", author: "Leonardo da Vinci", source: "Defterler" },
  { text: "Çoğumuz için en büyük tehlike, hedefimizi çok yüksek tutup ıskalamamız değil; çok alçak tutup ona ulaşmamızdır.", author: "Michelangelo", source: "Sanatçı Mektupları ve Biyografiler" },
  { text: "Mermerin içinde meleği gördüm ve onu özgür bırakana kadar yonttum.", author: "Michelangelo", source: "Vasari — Sanatçıların Hayatları" },
  { text: "Hâlâ öğreniyorum. (Ancora imparo.)", author: "Michelangelo", source: "87 Yaşındaki Notu" },
  { text: "Büyük şeyler bir dizi küçük şeyin bir araya gelmesiyle yapılır.", author: "Vincent van Gogh", source: "Theo'ya Mektup (22 Ekim 1882)" },
  { text: "İçinizden bir ses 'Resim yapamazsın' diyorsa, ne olursa olsun resim yapın; o ses susacaktır.", author: "Vincent van Gogh", source: "Theo'ya Mektuplar" },
  { text: "İlham vardır, ama sizi çalışırken bulması gerekir.", author: "Pablo Picasso", source: "Sanat Konuşmaları" },
  { text: "Eylem, tüm başarının temel anahtarıdır.", author: "Pablo Picasso", source: "Biyografik Söyleşiler" },
  { text: "İnsandan her şey alınabilir, tek bir şey hariç: Herhangi bir koşulda kendi tutumunu ve kendi yolunu seçme özgürlüğü.", author: "Viktor E. Frankl", source: "İnsanın Anlam Arayışı (1946)" },
  { text: "Koşulları değiştiremediğimiz zaman, kendimizi değiştirmeye davet ediliriz.", author: "Viktor E. Frankl", source: "İnsanın Anlam Arayışı" },
  { text: "Uyaran ile tepki arasında bir boşluk vardır. O boşlukta tepkimizi seçme gücümüz, tepkimizde ise gelişimimiz ve özgürlüğümüz yatar.", author: "Viktor E. Frankl", source: "Anlam Arayışı Geleneği" },
  { text: "Bilinçdışını bilinçli hale getirene kadar, o sizin hayatınızı yönlendirir ve siz buna kader dersiniz.", author: "Carl Gustav Jung", source: "Psikoloji ve Simya" },
  { text: "Başkalarında bizi rahatsız eden her şey, kendimizi daha iyi anlamamıza yol açabilir.", author: "Carl Gustav Jung", source: "Anılar, Düşler, Düşünceler" },
  { text: "Dışarıya bakan rüya görür; içeriye bakan uyanır.", author: "Carl Gustav Jung", source: "Mektuplar (1916)" },
  { text: "Ben bana ne olduğu değilim; ben ne olmayı seçtiğimim.", author: "Carl Gustav Jung", source: "Kırmızı Kitap / Yazılar" },
  { text: "Nereden geldiğiniz değil, nereye gittiğiniz hayatınızı belirler.", author: "Alfred Adler", source: "Yaşamın Anlam ve Amacı" },
  { text: "Yaratıcılık, kesinliklerden vazgeçme cesaretini gerektirir.", author: "Erich Fromm", source: "Sevme Sanatı" },
  { text: "Bana bir ağacı kesmek için altı saat verin, ilk dört saatini baltamı bilemekle geçiririm.", author: "Abraham Lincoln", source: "Başkanlık Anektodları" },
  { text: "Geleceği tahmin etmenin en güvenilir yolu, onu inşa etmektir.", author: "Abraham Lincoln", source: "Konuşmalar" },
  { text: "Sonunda önemli olan hayatımızdaki yıllar değil, yıllarımızdaki hayattır.", author: "Abraham Lincoln", source: "Hitabeler" },
  { text: "Bilgiye yapılan yatırım, her zaman en yüksek getiriyi sağlar.", author: "Benjamin Franklin", source: "Zenginlik Yolu (The Way to Wealth, 1758)" },
  { text: "Hazırlanmakta başarısız olarak, başarısız olmaya hazırlanırsınız.", author: "Benjamin Franklin", source: "Poor Richard's Almanack" },
  { text: "Bugün yapabileceğin işi asla yarına bırakma.", author: "Benjamin Franklin", source: "Poor Richard's Almanack" },
  { text: "Enerji ve ısrar her şeyi fetheder.", author: "Benjamin Franklin", source: "Poor Richard's Almanack (1750)" },
  { text: "Önümüzdeki ve arkamızdaki şeyler, içimizdeki şeylerin yanında çok küçük kalır.", author: "Ralph Waldo Emerson", source: "Denemeler — Özgüven (Self-Reliance)" },
  { text: "Her büyük başarı, başlangıçta bir coşkunun ürünüdür.", author: "Ralph Waldo Emerson", source: "Çemberler (Circles, 1841)" },
  { text: "Yolun seni götürdüğü yere gitme; bunun yerine yol olmayan yerden git ve arkanda bir iz bırak.", author: "Ralph Waldo Emerson", source: "Felsefi Denemeler" },
  { text: "Hayallerinizin yönünde güvenle ilerleyin; hayal ettiğiniz hayatı yaşamak için sadeleşin.", author: "Henry David Thoreau", source: "Walden — Ormanda Yaşam (1854)" },
  { text: "Bir şeyin maliyeti, onun karşılığında hayatınızdan hemen ya da uzun vadede ne kadar zaman verdiğinizdir.", author: "Henry David Thoreau", source: "Walden" },
  { text: "İlerlemenin sırrı, başlamaktır. Başlamanın sırrı ise karmaşık işleri yönetilebilir küçük parçalara bölüp ilk parçadan başlamaktır.", author: "Mark Twain", source: "Yazılar ve Notlar" },
  { text: "Bundan yirmi yıl sonra, yaptıklarınızdan çok yapmadıklarınız için pişman olacaksınız; öyleyse demir alın ve güvenli limandan çıkın.", author: "Mark Twain", source: "Amerikan Edebiyatı Geleneği" },
  { text: "Başkalarından üstün olmanın soylu bir yanı yoktur; gerçek soyluluk, dünkü kendinizden üstün olmaktır.", author: "Ernest Hemingway", source: "True at First Light (1923)" },
  { text: "İnsan yenilmek için yaratılmadı. İnsan yok edilebilir ama yenilmez.", author: "Ernest Hemingway", source: "Yaşlı Adam ve Deniz (1952)" },
  { text: "İlhamın gelmesini bekleyemezsiniz; elinize bir sopa alıp onun peşine düşmelisiniz.", author: "Jack London", source: "Martin Eden / Yazarlık Üzerine" },
  { text: "İnsanların söylediklerini unutabilirsin, yaptıklarını da unutabilirsin; ama sana nasıl hissettirdiklerini asla unutmazsın.", author: "Maya Angelou", source: "Söyleşiler ve Denemeler" },
  { text: "Sevdiğin şeyi değiştiremiyorsan, ona bakış açını ve kendi tutumunu değiştir.", author: "Maya Angelou", source: "Kızıma Mektup (Letter to My Daughter)" },

  // 346 - 387: Ekstra Klasik Düşünürler ve Bilim İnsanları (Toplam 387 Özgün Gerçek Alıntı)
  { text: "Zamanın kıymetini en çok onu kaybedenler anlar; oysa bilge insan zamanı kaybetmeden önce değerlendirir.", author: "Dante Alighieri", source: "Araf (Purgatorio), 3. Kanto" },
  { text: "Eğitimli bir zihnin işareti, bir düşünceyi kabul etmeden de onu tartabilmesidir.", author: "Aristoteles", source: "Metafizik / Etik Geleneği" },
  { text: "Mutluluk hazır bir şey değildir; kendi eylemlerinizden doğar.", author: "Dalai Lama", source: "Mutluluk Sanatı" },
  { text: "Bir mum olmak kolay değildir; ışık saçmak için önce yanmak gerekir.", author: "Mevlânâ Celâleddîn-i Rûmî", source: "Dîvân-ı Kebîr" },
  { text: "Zor işler, zamanında yapmadığımız kolay işlerin birikmesiyle oluşur.", author: "Henry Ford", source: "Hayatım ve İşim (My Life and Work, 1922)" },
  { text: "Yapabileceğinizi düşünseniz de, yapamayacağınızı düşünseniz de haklısınız.", author: "Henry Ford", source: "Reader's Digest (1947)" },
  { text: "Dehanın yüzde biri ilham, yüzde doksan dokuzu alın teridir.", author: "Thomas Alva Edison", source: "Harper's Monthly (Eylül 1932)" },
  { text: "Ben başarısız olmadım; sadece işe yaramayan on bin yol buldum.", author: "Thomas Alva Edison", source: "Biyografi (1910)" },
  { text: "Disiplin, hedefler ile başarı arasındaki köprüdür.", author: "Jim Rohn", source: "Zenginlik ve Mutluluk İçin 7 Strateji" },
  { text: "Motivasyon başlamanızı sağlar; alışkanlık ise devam etmenizi.", author: "Jim Ryun", source: "Olimpiyat Röportajları" },
  { text: "Kazanma isteği önemlidir, ama hazırlanma isteği hayati önem taşır.", author: "Joe Paterno", source: "Liderlik Konuşmaları" },
  { text: "Hayatta sahip olabileceğiniz en büyük ayrıcalık, uğruna çok çalışmaya değer bir işinizin olmasıdır.", author: "Theodore Roosevelt", source: "Labor Day Konuşması (1903)" },
  { text: "Yapabildiğin yerde, elindekilerle, yapabileceğini yap.", author: "Theodore Roosevelt", source: "Otobiyografi (1913)" },
  { text: "Önemli olan eleştirmen değil; arenada ter ve toz içinde mücadele eden, düşse bile tekrar kalkan insandır.", author: "Theodore Roosevelt", source: "Cumhuriyette Yurttaşlık Konuşması, Sorbonne (1910)" },
  { text: "Korkmamız gereken tek şey, korkunun kendisidir.", author: "Franklin D. Roosevelt", source: "İlk Başkanlık Açılış Konuşması (4 Mart 1933)" },
  { text: "Sakin bir deniz hiçbir zaman usta bir denizci yetiştirmez.", author: "Franklin D. Roosevelt", source: "Mektuplar" },
  { text: "Başarı son değildir, başarısızlık ise ölümcül değildir: Önemli olan devam etme cesaretidir.", author: "Winston Churchill", source: "Hitabeler" },
  { text: "Uçurtmalar rüzgârla birlikte değil, rüzgâra karşı koydukları için yükselirler.", author: "Winston Churchill", source: "Avam Kamarası Konuşmaları" },
  { text: "Her günü hayatının en güzel günü olabilmesi için bir şans ver.", author: "Mark Twain", source: "Takvim Notları" },
  { text: "İyimserlik, başarıya götüren inançtır; umut ve güven olmadan hiçbir şey yapılamaz.", author: "Helen Keller", source: "İyimserlik (Optimism, 1903)" },
  { text: "Hayat ya cesur bir maceradır ya da hiçbir şeydir.", author: "Helen Keller", source: "Açık Kapı (The Open Door, 1957)" },
  { text: "Dünyada görmek istediğiniz değişimin kendisi olun.", author: "Mahatma Gandhi", source: "Toplu Yazılar (1913)" },
  { text: "Yarın ölecekmiş gibi yaşa; sonsuza dek yaşayacakmış gibi öğren.", author: "Mahatma Gandhi", source: "Yazılar ve Konuşmalar" },
  { text: "Yapılana kadar her şey imkânsız görünür.", author: "Nelson Mandela", source: "Özgürlüğe Uzun Yürüyüş" },
  { text: "Eğitim, dünyayı değiştirmek için kullanabileceğiniz en güçlü silahtır.", author: "Nelson Mandela", source: "Johannesburg Konuşması (16 Temmuz 2003)" },
  { text: "Beni başarılarımla değil, kaç kez düştükten sonra tekrar ayağa kalktığımla yargılayın.", author: "Nelson Mandela", source: "Konuşmalar" },
  { text: "Uçamıyorsan koş, koşamazsan yürü, yürüyemiyorsan sürün; ama ne yaparsan yap ilerlemeye devam et.", author: "Martin Luther King Jr.", source: "Spelman College Konuşması (10 Nisan 1960)" },
  { text: "Karanlık karanlığı kovamaz; bunu yalnızca ışık yapabilir. Nefret nefreti kovamaz; bunu yalnızca sevgi yapabilir.", author: "Martin Luther King Jr.", source: "Sevme Gücü (Strength to Love, 1963)" },
  { text: "Doğru olanı yapmak için zaman her zaman doğrudur.", author: "Martin Luther King Jr.", source: "Oberlin College Konuşması (1964)" },
  { text: "Tohum toprağın karanlığından korksaydı, hiçbir zaman güneşe uzanan bir çınar olamazdı.", author: "Halil Cibran", source: "Gezgin (The Wanderer)" }
];
